const { EventEmitter } = require('node:events');
const bus = new EventEmitter();

// لازم مستمع لحدث error دائمًا لتفادي توقّف العملية
bus.on('error', (err) => {
  console.error('حدث خطأ:', err.message);
});

const hadListeners = bus.emit('error', new Error('فشل الاتصال'));
console.log(hadListeners); // true

const http = require('node:http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ message: 'أهلًا بك' }));
});

server.listen(3000, () => {
  console.log('الخادم يعمل على المنفذ 3000');
});

const crypto = require('node:crypto');

// متزامن
const token = crypto.randomBytes(16).toString('hex');
console.log(token); // مثلًا: '9f86d081884c7d65...'

// غير متزامن
crypto.randomBytes(16, (err, buf) => {
  if (err) throw err;
  console.log(buf.toString('hex'));
});

const crypto = require('node:crypto');

const hash = crypto.createHash('sha256');
hash.update('نص أريد تجزئته');
const digest = hash.digest('hex');
console.log(digest);

// دمج أكثر من قطعة بيانات:
const hash2 = crypto.createHash('sha256');
hash2.update('جزء أول ');
hash2.update('جزء ثاني');
console.log(hash2.digest('hex'));

const { promisify } = require('node:util');
const fs = require('node:fs');

const readFileAsync = promisify(fs.readFile);

async function loadNotes() {
  try {
    const data = await readFileAsync('notes.txt', 'utf8');
    console.log(data);
  } catch (err) {
    console.error('فشلت القراءة:', err.message);
  }
}

loadNotes();

const { createZipArchiveSync, ZipEntry } = require('node:zlib');
const fs = require('node:fs');

const entries = [
  ZipEntry.createSync('readme.txt', Buffer.from('محتوى الملف الأول')),
  ZipEntry.createSync('data/notes.txt', Buffer.from('ملاحظات إضافية')),
];

const zipBuffer = createZipArchiveSync(entries);
fs.writeFileSync('output.zip', zipBuffer);
console.log('تم إنشاء الأرشيف بنجاح');

const { ZipFile } = require('node:zlib');

async function readArchive() {
  const zip = await ZipFile.open('output.zip');
  console.log(`عدد العناصر: ${zip.size}`);

  const entry = await zip.get('readme.txt');
  const content = await entry.content();
  console.log(content.toString('utf8'));

  await zip.close();
}

readArchive();

const { ZipEntry, ZipFile } = require('node:zlib');

async function addReportToArchive() {
  const zip = await ZipFile.open('output.zip', { writable: true });

  await zip.add('reports/august.txt', Buffer.from('تقرير آب'), {
    method: 'store', // بدون ضغط، مناسب لملف صغير
  });

  await zip.close();
}

addReportToArchive();
